/// <summary>
/// Extension of the <c>WhsLicensePlateLabelPrintCommandGenerator</c> class for the
/// AAXWarehouseTools model. Stages labels printed through the label layout path, which produces
/// no printable ZPL downstream when no printer is configured.
/// </summary>
[ExtensionOf(classStr(WhsLicensePlateLabelPrintCommandGenerator))]
final class WhsLicensePlateLabelPrintCommandGenerator_AAXWarehouseTools_Extension
{
}

Method.Source:
/// <summary>
/// Extends <c>printLabelsForLicensePlate</c> to stage the label layout line in the active
/// capture scope after the base implementation is called with <c>next</c>. Capture is best
/// effort and never disrupts the print.
/// </summary>
/// <param name = "_licensePlateRoutingLine">The document routing label layout line.</param>
/// <param name = "_licensePlateLabel">The license plate label being printed.</param>
/// <param name = "_labelPrinterSelector">The label printer selector.</param>
/// <returns>The number of labels printed by the base implementation.</returns>
public static int printLabelsForLicensePlate(
    WHSDocumentRoutingLabelLayoutLine  _licensePlateRoutingLine,
    WHSLicensePlateLabel               _licensePlateLabel,
    WHSLabelPrinterSelector            _labelPrinterSelector)
{
    int ret = next printLabelsForLicensePlate(_licensePlateRoutingLine, _licensePlateLabel, _labelPrinterSelector);

    // The capture scope is opened by printDocument and carries the capture gate
    AAXWHSLabelCaptureScope scope = AAXWHSLabelCaptureScope::current();
    if (scope && scope.isActive())
    {
        try
        {
            scope.stageLabelLayoutLine(_licensePlateRoutingLine, _licensePlateLabel);
        }
        catch
        {
            // A capture failure must never disrupt the print
        }
    }

    return ret;
}
